args:
{
  "messages": [
    {
      "version": "1.0",
      "createSurface": {
        "surfaceId": "reservation",
        "dataModel": {
          "selectedDateTime": ""
        },
        "components": [
          {
            "id": "root",
            "component": "Column",
            "children": ["dateTimePicker", "confirmButton", "divider", "resultCard"]
          },
          {
            "id": "dateTimePicker",
            "component": "DateTimeInput",
            "label": "예약 날짜 및 시간",
            "value": { "path": "/selectedDateTime" },
            "enableDate": true,
            "enableTime": true
          },
          {
            "id": "confirmButton",
            "component": "Button",
            "child": "confirmLabel",
            "variant": "primary",
            "action": {
              "event": {
                "name": "confirm",
                "context": {
                  "selectedDateTime": { "path": "/selectedDateTime" }
                }
              }
            }
          },
          {
            "id": "confirmLabel",
            "component": "Text",
            "text": "확인"
          },
          {
            "id": "divider",
            "component": "Divider"
          },
          {
            "id": "resultCard",
            "component": "Card",
            "child": "cardContent"
          },
          {
            "id": "cardContent",
            "component": "Column",
            "children": ["headerText", "resultText"]
          },
          {
            "id": "headerText",
            "component": "Text",
            "text": "선택된 예약 정보"
          },
          {
            "id": "resultText",
            "component": "Text",
            "text": { "path": "/selectedDateTime" }
          }
        ]
      }
    }
  ]
}
